import{_ as o,o as d,c as t,an as i}from"./chunks/framework.C_GApDaI.js";const _=JSON.parse('{"title":"Julia posteriordb implementations","description":"","frontmatter":{},"headers":[],"relativePath":"examples/posteriordb-implementations.md","filePath":"examples/posteriordb-implementations.md","lastUpdated":null}'),n={name:"examples/posteriordb-implementations.md"};function a(c,e,s,r,l,p){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="Julia-posteriordb-implementations" tabindex="-1">Julia posteriordb implementations <a class="header-anchor" href="#Julia-posteriordb-implementations" aria-label="Permalink to &quot;Julia posteriordb implementations {#Julia-posteriordb-implementations}&quot;">​</a></h1><p>StanBlocks keeps its PosteriorDB implementations in the optional <a href="https://github.com/nsiccha/StanBlocks.jl/blob/devibe/ext/PosteriorDBExt.jl" target="_blank" rel="noreferrer"><code>PosteriorDBExt</code> extension</a>. Loading <code>PosteriorDB</code> activates that extension and adds <code>slic_implementation(::Val{:model_name}; data...)</code> methods for the supported catalogue entries.</p><h2 id="Why-this-page-links-to-the-extension" tabindex="-1">Why this page links to the extension <a class="header-anchor" href="#Why-this-page-links-to-the-extension" aria-label="Permalink to &quot;Why this page links to the extension {#Why-this-page-links-to-the-extension}&quot;">​</a></h2><p>The legacy Quarto page used an include directive to paste the entire extension source into the rendered notebook. That produced a second, enormous copy of a maintained source file without turning it into a worked example. In the main docs, the extension itself is the canonical, line-addressable implementation; copying it here would drift immediately.</p><p>The implementations demonstrate a consistent set of StanBlocks mechanisms:</p><ul><li><p>per-model <code>Val</code> dispatch selects an implementation without a stringly typed runtime switch;</p></li><li><p><code>@deffun</code> supplies catalogue-specific recurrences and likelihood helpers;</p></li><li><p><code>@lhs</code>/<code>@lpxf</code> register custom distribution families for ordinary <code>~</code> statements and generated likelihood/prediction companions;</p></li><li><p><code>@slic</code> attaches PosteriorDB data and builds each model from the same public authoring surface used elsewhere in these examples.</p></li></ul><h2 id="Maintained-model-inventory" tabindex="-1">Maintained model inventory <a class="header-anchor" href="#Maintained-model-inventory" aria-label="Permalink to &quot;Maintained model inventory {#Maintained-model-inventory}&quot;">​</a></h2><p>The extension currently defines 77 named implementations. Related names are variants of one statistical example rather than unrelated snippets:</p><ul><li><p><strong>Generic GLM, rate, and introductory models:</strong> <code>GLM_Binomial_model</code>, <code>GLM_Poisson_model</code>, <code>GLMM_Poisson_model</code>, <code>Rate_1_model</code>, <code>Rate_2_model</code>, <code>Rate_3_model</code>, <code>Rate_4_model</code>, <code>Rate_5_model</code>, <code>blr</code>, <code>logistic_regression_rhs</code>, <code>pilots</code>, <code>surgical_model</code>, <code>diamonds</code>, <code>dugongs_model</code>, <code>kilpisjarvi</code>, and <code>accel_splines</code>. These cover binomial and Poisson regression, random effects, nonlinear growth, and spline bases.</p></li><li><p><strong>Canonical hierarchical and applied examples:</strong> <code>eight_schools_centered</code>, <code>eight_schools_noncentered</code>, <code>seeds_model</code>, <code>seeds_centered_model</code>, <code>seeds_stanified_model</code>, <code>sesame_one_pred_a</code>, <code>election88_full</code>, <code>nes</code>, <code>nes_logit_model</code>, and <code>bym2_offset_only</code>. The paired names expose centered/non-centred parameterisations or alternative spellings of the same likelihood.</p></li><li><p><strong>Child test-score regressions:</strong> <code>kidscore_momhs</code>, <code>kidscore_momiq</code>, <code>kidscore_momhsiq</code>, <code>kidscore_mom_work</code>, <code>kidscore_interaction</code>, <code>kidscore_interaction_c</code>, <code>kidscore_interaction_c2</code>, and <code>kidscore_interaction_z</code>. The suffixes add predictors, interactions, centering, or standardisation while preserving the same outcome.</p></li><li><p><strong>Earnings and height regressions:</strong> <code>earn_height</code>, <code>log10earn_height</code>, <code>log10earn_height_male</code>, <code>logearn_height</code>, <code>logearn_height_male</code>, <code>logearn_interaction</code>, <code>logearn_interaction_z</code>, and <code>logearn_logheight_male</code>. These make the response/predictor transforms and sex interaction explicit in the implementation name.</p></li><li><p><strong>Mesquite regressions:</strong> <code>mesquite</code>, <code>logmesquite</code>, <code>logmesquite_logvolume</code>, <code>logmesquite_logva</code>, <code>logmesquite_logvas</code>, and <code>logmesquite_logvash</code>. Successive variants change the response scale and add transformed canopy, shrub, and height predictors.</p></li><li><p><strong>Well-switching regressions:</strong> <code>wells_dist</code>, <code>wells_dist100_model</code>, <code>wells_dist100ars_model</code>, <code>wells_dae_model</code>, <code>wells_dae_c_model</code>, <code>wells_dae_inter_model</code>, <code>wells_daae_c_model</code>, <code>wells_interaction_model</code>, and <code>wells_interaction_c_model</code>. The family varies distance scaling, arsenic, education, interactions, and centered predictors.</p></li><li><p><strong>Radon multilevel family:</strong> <code>radon_pooled</code>, <code>radon_county</code>, <code>radon_county_intercept</code>, <code>radon_partially_pooled_centered</code>, <code>radon_partially_pooled_noncentered</code>, <code>radon_hierarchical_intercept_centered</code>, <code>radon_hierarchical_intercept_noncentered</code>, <code>radon_variable_intercept_centered</code>, <code>radon_variable_intercept_noncentered</code>, <code>radon_variable_slope_centered</code>, <code>radon_variable_slope_noncentered</code>, <code>radon_variable_intercept_slope_centered</code>, and <code>radon_variable_intercept_slope_noncentered</code>. Together they cover the pooling ladder and the centered/non-centred hierarchy choices.</p></li><li><p><strong>Time-series, Gaussian-process, mixture, and spatial specialists:</strong> <code>arma11</code>, <code>garch11</code>, <code>gp_regr</code>, <code>gp_pois_regr</code>, <code>normal_mixture</code>, <code>low_dim_gauss_mix</code>, and <code>low_dim_gauss_mix_collapse</code>. These are where the extension-local recurrence, custom-density, GP, and mixture helpers are most visible.</p></li></ul><p>This inventory is intentionally explanatory rather than a pasted source dump. For example, every <code>_centered</code>/<code>_noncentered</code> pair is a parameterisation comparison, while the radon, wells, kid-score, earnings, and mesquite suffixes record the covariate/model-building progression. The full method bodies at the source link remain the executable authority.</p><p>For small, side-by-side executable examples of those mechanisms, use the <a href="./../feature-atlas">feature atlas</a>. For the complete catalogue mapping, read the extension source above; it is what the package loads and tests.</p>',11)])])}const h=o(n,[["render",a]]);export{_ as __pageData,h as default};
